package com.bank.stream.model;

// One row of the aggregate result table (account → count).
public class ResultRow {
    private final String accountId;
    private final long count;
    private final boolean changedThisTrigger;

    public ResultRow(String accountId, long count, boolean changedThisTrigger) {
        this.accountId = accountId;
        this.count = count;
        this.changedThisTrigger = changedThisTrigger;
    }

    public String getAccountId() { return accountId; }
    public long getCount() { return count; }
    public boolean isChangedThisTrigger() { return changedThisTrigger; }

    @Override public String toString() { return accountId + "=" + count; }
}
