package com.bank.stream.service;

import com.bank.stream.model.ResultRow;
import java.util.List;
import java.util.stream.Collectors;

// Shows what each output mode emits from the same result table snapshot.
public class OutputModeEmitter {

    // Complete: the entire result table is re-emitted.
    public List<ResultRow> complete(List<ResultRow> resultTable) {
        return List.copyOf(resultTable);
    }

    // Update: only rows that changed this trigger are emitted.
    public List<ResultRow> update(List<ResultRow> resultTable) {
        return resultTable.stream()
                .filter(ResultRow::isChangedThisTrigger)
                .collect(Collectors.toList());
    }

    // Append: only final, never-to-change rows (here, changed rows past watermark).
    // Simulated: a finalized flag would come from the watermark in real Spark.
    public List<ResultRow> append(List<ResultRow> finalizedRows) {
        return List.copyOf(finalizedRows);
    }
}
