package com.bank.stream;

import com.bank.stream.model.ResultRow;
import com.bank.stream.service.OutputModeEmitter;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

// Runnable demo: compare Append, Complete and Update for one micro-batch.
public class OutputModeDemo {

    private static final Logger log = Logger.getLogger(OutputModeDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFormatter(new Formatter() {
            @Override public String format(LogRecord r) {
                return String.format("%1$tF %1$tT %2$-7s %3$s%n",
                        new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
            }
        });
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        OutputModeEmitter emitter = new OutputModeEmitter();

        // Result table after a micro-batch: SAV2001 and CUR3001 changed, SAV9999 did not.
        List<ResultRow> resultTable = List.of(
            new ResultRow("SAV2001", 3, true),
            new ResultRow("CUR3001", 2, true),
            new ResultRow("SAV9999", 7, false));

        // Finalized rows past the watermark (only these are Append-eligible).
        List<ResultRow> finalized = List.of(new ResultRow("SAV9999", 7, false));

        log.info(() -> "COMPLETE emits whole table: " + emitter.complete(resultTable));
        log.info(() -> "UPDATE emits changed rows:  " + emitter.update(resultTable));
        log.info(() -> "APPEND emits finalized rows: " + emitter.append(finalized));
        log.info("Output mode comparison complete.");
    }
}
